import struct

# Implementasi Simulator Serialisasi Biner Bergaya Apache Avro (Zigzag Varint + Length-Prefixed String)
class AvroBinaryEncoder:
    @staticmethod
    def encode_zigzag_varint(n):
        # Zigzag encoding: memetakan integer bertanda ke unsigned integer
        z = (n << 1) ^ (n >> 63) if n >= 0 else (~n << 1) | 1
        buf = bytearray()
        while (z & ~0x7F) != 0:
            buf.append((z & 0x7F) | 0x80)
            z >>= 7
        buf.append(z & 0x7F)
        return bytes(buf)

    @staticmethod
    def encode_string(s):
        utf8_bytes = s.encode('utf-8')
        # Avro menyimpan string sebagai: [varint_length] + [raw_utf8_bytes]
        length_header = AvroBinaryEncoder.encode_zigzag_varint(len(utf8_bytes))
        return length_header + utf8_bytes

    @staticmethod
    def serialize_record(schema, record):
        payload = bytearray()
        for field_name, field_type in schema:
            val = record[field_name]
            if field_type == 'int':
                payload.extend(AvroBinaryEncoder.encode_zigzag_varint(val))
            elif field_type == 'string':
                payload.extend(AvroBinaryEncoder.encode_string(val))
            elif field_type == 'float':
                payload.extend(struct.pack('<f', float(val)))
        return bytes(payload)

# Skema Avro: Record event transaksi perbankan
schema_def = [
    ('account_id', 'int'),
    ('action_type', 'string'),
    ('amount', 'float')
]

sample_record = {
    'account_id': 10452,
    'action_type': 'TRANSFER',
    'amount': 250.75
}

avro_bin = AvroBinaryEncoder.serialize_record(schema_def, sample_record)
json_equivalent = '{"account_id":10452,"action_type":"TRANSFER","amount":250.75}'.encode('utf-8')

print(f'Evaluasi Format Serialisasi Apache Avro:')
print(f'  Data Asli: {sample_record}')
print(f'  Biner Avro Payload (Hex): {avro_bin.hex()} ({len(avro_bin)} bytes)')
print(f'  Ukuran Ekuivalen JSON  : {len(json_equivalent)} bytes')
print(f'  Rasio Reduksi Payload  : {(1 - len(avro_bin) / len(json_equivalent)) * 100:.1f}% lebih ringkas!')
print('  Karakteristik Kunci: Bebas overhead nama field di wire format berkat schema contract terpisah.')

import numpy as np

# Implementasi Simulator Schema Evolution: Type Widening & Default Value Injection
class SchemaEvolutionEngine:
    @staticmethod
    def read_record_with_evolved_schema(old_record, old_schema, new_schema):
        evolved_record = {}
        for field_name, field_def in new_schema.items():
            target_type = field_def['type']
            default_val = field_def.get('default', None)

            if field_name in old_record:
                val = old_record[field_name]
                src_type = old_schema[field_name]['type']

                # 1. Type Promotion / Widening Rule
                if src_type == target_type:
                    evolved_record[field_name] = val
                elif src_type == 'int32' and target_type == 'int64':
                    evolved_record[field_name] = int(val)
                elif src_type == 'float32' and target_type == 'float64':
                    evolved_record[field_name] = float(val)
                else:
                    raise ValueError(f'Incompatible Type Promotion: {src_type} -> {target_type}')
            else:
                # 2. Add Column Rule: Injeksi default value untuk file lama
                evolved_record[field_name] = default_val
        return evolved_record

# Skema Versi 1 (Tahun 2024)
schema_v1 = {
    'id': {'type': 'int32'},
    'amount': {'type': 'float32'}
}
record_v1 = {'id': 101, 'amount': 45.5}

# Skema Versi 2 (Tahun 2026): id di-promote ke int64, ditambah kolom baru 'currency'
schema_v2 = {
    'id': {'type': 'int64'},
    'amount': {'type': 'float64'},
    'currency': {'type': 'string', 'default': 'USD'}
}

evolved = SchemaEvolutionEngine.read_record_with_evolved_schema(record_v1, schema_v1, schema_v2)

print(f'Evaluasi Mekanisme Schema Evolution:')
print(f'  Record Versi Lama (V1): {record_v1}')
print(f'  Hasil Pembacaan dengan Skema Baru (V2): {evolved}')
print(f'  Verifikasi Kolom Baru: currency = "{evolved["currency"]}" (Diisi default otomatis)')
print('  Kesimpulan: Data historis tetap valid dibaca tanpa proses rewriting storage masif.')

